    SELECT ym.`Date`, ym.`Consumption`
    FROM yearmonth AS ym
    INNER JOIN customers AS c ON ym.`CustomerID` = c.`CustomerID`
)
SELECT * FROM t_join;

WITH t_date AS (
    SELECT `Date`, `Consumption`
    FROM t_join
    WHERE `Date` IS NOT NULL
)
SELECT * FROM t_date;

WITH c_date AS (
    SELECT `Date`, `Consumption`
    FROM t_join
    ORDER BY `Consumption` DESC
)
SELECT * FROM c_date;

WITH c_date AS (
    SELECT STRFTIME('%Y', `Date`) AS year, `Consumption`
    FROM t_date
)
SELECT * FROM c_date;

